class Solution {
public:
    int maximumWealth(vector<vector<int>>& accounts) {
        int max_wealth = 0;
        for(int i=0; i<accounts.size(); i++){
            int sum = 0;
            for(int j=0; j<accounts[i].size(); j++){
                sum = sum + accounts[i][j];
            }
            if(sum > max_wealth){
                max_wealth = sum;
            }
        }
        return max_wealth;
    }
};

number-of-steps-to-reduce-a-number-to-ze.work:
class Solution {
public:
    int numberOfSteps(int num) {
        int step_count = 0;
        while(num != 0){
            if(num%2 == 0){
                num = num/2;
                step_count ++;
            }else{
                num = num - 1;
                step_count ++;
            }
        }
        return step_count;
    }
};

