subtract-the-product-and-sum-of-digits-o.work:
class Solution {
public:
    int subtractProductAndSum(int n) {
        int sum = 0;
        int prod = 1;
        while(n!=0){
            int digit = n%10;
            sum = sum + digit;
            prod = prod * digit;
            n = n/10;
        }
        return prod-sum;
    }
};

