difference-between-element-sum-and-digit.work:
class Solution {
public:
    int differenceOfSum(vector<int>& nums) {
        int ele_sum = 0;
        int dig_sum = 0;
        for(int i=0; i<nums.size(); i++){
            ele_sum = ele_sum + nums[i];
            while(nums[i] != 0){
                int last = nums[i] % 10;
                dig_sum = dig_sum + last;
                nums[i] = nums[i] / 10;
            }
        }
        return abs(ele_sum - dig_sum);
    }
};

sign-of-the-product-of-an-array.work:
class Solution {
public:
    int signFunc(int prod_sign){
        if(prod_sign == 0){
            return 1;
        }else{
            return -1;
        }
    }

    int arraySign(vector<int>& nums) {
        int prod_non_zero = 1;
        int neg_no = 0;
        for(int i=0; i<nums.size(); i++){
            if(nums[i] == 0){
                prod_non_zero = 0;
                break;
            }
            if(nums[i] < 0){
                neg_no++;
            }
        }

        if(prod_non_zero == 0){
            return 0;
        }else{
            return signFunc(neg_no%2);
        }

    }
};

