class Solution {
public:
    bool isPalindrome(int x) {
        if(x < 0){
            return false;
        }
        int num = x;
        long long rev_num = 0;
        while(num != 0){
            int digit = num % 10;
            rev_num = rev_num*10 + digit;
            num = num / 10;
        }
        if(rev_num == x){
            return true;
        }else{
            return false;
        }
    }
};

average-salary-excluding-the-minimum-and.work:
class Solution {
public:
    double average(vector<int>& salary) {
        double max= salary[0];
        double min = salary[0];
        double total = salary[0];
        for(int i=1 ; i< salary.size(); i++){
            total = total + salary[i];
            if(max < salary[i]){
                max = salary[i];
            }
            if(min > salary[i]){
                min = salary[i];
            }
        }

        return (total-(max+min))/(salary.size()-2);
    }
};

reverse-integer.work:
class Solution {
public:
    int reverse(int x) {
        long long rev = 0;

        while (x != 0) {
            int digit = x % 10;
            rev = rev * 10 + digit;
            x = x / 10;
        }

        if (rev > INT_MAX || rev < INT_MIN) {
            return 0;
        }

        return (int)rev;
    }
};

add-digits.work:
class Solution {
public:
    int addDigits(int num) {
        if(num<10){
            return num;
        }
        int n = num;
        int digi_sum = 0;
        while(n > 9){
            while(n!=0){
                int digit = n%10;
                digi_sum += digit;
                n = n/10;
            }
            if(digi_sum > 9){
                n = digi_sum;
                digi_sum = 0;
            }
        }
        return digi_sum;
    }
};
